/* ============================================
   Orchard — Premium Tech E-Commerce Store
   ============================================ */

/* CSS Variables */
:root {
  --color-bg: #ffffff;
  --color-bg-secondary: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-accent: #0066cc;
  --color-accent-hover: #0077ed;
  --color-border: #d2d2d7;
  --color-card-bg: #f5f5f7;
  --font-stack: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1024px;
  --section-padding: 60px 0;
  --card-radius: 18px;
  --transition: all 0.3s cubic-bezier(0.25, 0.1, 0.25, 1);
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-stack);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.47059;
  font-weight: 400;
  letter-spacing: -0.022em;
  overflow-x: hidden;
}

a {
  color: var(--color-accent);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Utility */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
}

.section-title {
  font-size: 40px;
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.003em;
  text-align: center;
  margin-bottom: 8px;
}

.section-subtitle {
  font-size: 21px;
  font-weight: 400;
  line-height: 1.381;
  letter-spacing: -0.021em;
  text-align: center;
  color: var(--color-text-secondary);
  margin-bottom: 32px;
}

/* Header / Navigation */
.header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 22px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-size: 20px;
  font-weight: 600;
  color: var(--color-text);
  text-decoration: none;
}

.logo:hover {
  text-decoration: none;
}

.nav-links {
  display: flex;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  font-size: 12px;
  font-weight: 400;
  color: var(--color-text);
  opacity: 0.8;
  letter-spacing: -0.01em;
}

.nav-links a:hover {
  opacity: 1;
  text-decoration: none;
  color: var(--color-text);
}

.nav-links a.active {
  opacity: 1;
  font-weight: 500;
}

/* Ribbon Banner */
.ribbon-banner {
  background: var(--color-bg-secondary);
  text-align: center;
  padding: 12px 22px;
  font-size: 14px;
  line-height: 1.4;
}

.ribbon-banner a {
  color: var(--color-accent);
}

/* Hero Section */
.hero {
  text-align: center;
  padding: 60px 22px 40px;
}

.hero-title {
  font-size: 56px;
  font-weight: 600;
  line-height: 1.07143;
  letter-spacing: -0.005em;
  margin-bottom: 12px;
}

.hero-subtitle {
  font-size: 28px;
  font-weight: 400;
  line-height: 1.14286;
  letter-spacing: -0.021em;
  color: var(--color-text-secondary);
  margin-bottom: 24px;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.cta-link {
  font-size: 17px;
  color: var(--color-accent);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.cta-link::after {
  content: "›";
  font-size: 20px;
  line-height: 1;
}

/* Product Grid (Homepage) */
.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  padding: 0 16px 60px;
  max-width: 1260px;
  margin: 0 auto;
}

.product-tile {
  background: var(--color-card-bg);
  border-radius: var(--card-radius);
  padding: 48px 24px 40px;
  text-align: center;
  min-height: 520px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  position: relative;
  overflow: hidden;
  transition: var(--transition);
}

.product-tile:hover {
  transform: scale(1.01);
}

.product-tile.full-width {
  grid-column: 1 / -1;
}

.tile-headline {
  font-size: 40px;
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.003em;
  margin-bottom: 8px;
}

.tile-tagline {
  font-size: 21px;
  font-weight: 400;
  line-height: 1.381;
  letter-spacing: -0.021em;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
  max-width: 420px;
}

.tile-ctas {
  display: flex;
  gap: 20px;
  justify-content: center;
  margin-bottom: 32px;
}

.btn {
  font-size: 14px;
  font-weight: 400;
  padding: 8px 16px;
  border-radius: 980px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: var(--transition);
}

.btn-primary {
  background: var(--color-accent);
  color: #fff;
}

.btn-primary:hover {
  background: var(--color-accent-hover);
  text-decoration: none;
}

.btn-secondary {
  background: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
}

.btn-secondary:hover {
  background: var(--color-accent);
  color: #fff;
  text-decoration: none;
}

.tile-image {
  width: 100%;
  max-width: 400px;
  height: 280px;
  object-fit: contain;
  margin-top: auto;
}

/* Carousel */
.carousel-section {
  padding: var(--section-padding);
  overflow: hidden;
}

.carousel-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 20px;
  padding: 0 22px;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}

.carousel-title {
  font-size: 28px;
  font-weight: 600;
  line-height: 1.14286;
  letter-spacing: -0.021em;
}

.carousel-subtitle {
  font-size: 17px;
  color: var(--color-text-secondary);
  margin-top: 4px;
}

.carousel-controls {
  display: flex;
  gap: 12px;
}

.carousel-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.05);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: var(--color-text);
  transition: var(--transition);
}

.carousel-btn:hover {
  background: rgba(0, 0, 0, 0.1);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-track-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding: 0 22px;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-card {
  flex: 0 0 auto;
  scroll-snap-align: start;
  width: 320px;
  background: var(--color-card-bg);
  border-radius: var(--card-radius);
  padding: 24px;
  display: flex;
  flex-direction: column;
  transition: var(--transition);
}

.carousel-card:hover {
  transform: translateY(-4px);
}

.carousel-card.wide {
  width: 400px;
}

.carousel-card .badge {
  font-size: 12px;
  font-weight: 600;
  color: #bf4800;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.carousel-card .card-title {
  font-size: 21px;
  font-weight: 600;
  line-height: 1.19048;
  letter-spacing: -0.021em;
  margin-bottom: 6px;
}

.carousel-card .card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
  margin-bottom: 12px;
  flex-grow: 1;
}

.carousel-card .card-price {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 4px;
}

.carousel-card .card-monthly {
  font-size: 12px;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
}

.carousel-card .card-image {
  width: 100%;
  height: 180px;
  object-fit: contain;
  margin-top: auto;
}

/* Icon Bar */
.icon-bar {
  display: flex;
  gap: 32px;
  justify-content: center;
  flex-wrap: wrap;
  padding: 40px 22px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  color: var(--color-text);
  font-size: 13px;
  font-weight: 500;
  transition: var(--transition);
}

.icon-bar-item:hover {
  text-decoration: none;
  color: var(--color-accent);
}

.icon-bar-item .icon-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-card-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

/* Entertainment Tabs */
.entertainment-section {
  padding: var(--section-padding);
  background: var(--color-bg);
}

.tab-nav {
  display: flex;
  gap: 32px;
  justify-content: center;
  margin-bottom: 32px;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 12px;
}

.tab-btn {
  font-size: 17px;
  font-weight: 400;
  color: var(--color-text-secondary);
  padding: 4px 0;
  position: relative;
  transition: var(--transition);
}

.tab-btn:hover {
  color: var(--color-text);
}

.tab-btn.active {
  color: var(--color-text);
  font-weight: 500;
}

.tab-btn.active::after {
  content: "";
  position: absolute;
  bottom: -13px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-text);
}

.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
}

.tab-cards {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding: 0 22px;
  max-width: var(--max-width);
  margin: 0 auto;
  scrollbar-width: none;
}

.tab-cards::-webkit-scrollbar {
  display: none;
}

.tab-card {
  flex: 0 0 auto;
  scroll-snap-align: start;
  width: 320px;
  height: 420px;
  border-radius: var(--card-radius);
  overflow: hidden;
  position: relative;
  background: linear-gradient(180deg, #1d1d1f 0%, #434344 100%);
  color: #fff;
  padding: 32px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.tab-card .tab-card-title {
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 8px;
}

.tab-card .tab-card-desc {
  font-size: 14px;
  opacity: 0.8;
  margin-bottom: 16px;
}

.tab-card .tab-card-cta {
  color: #fff;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.tab-card .tab-card-cta::after {
  content: "›";
  font-size: 16px;
}

/* Help & Store Difference Cards */
.help-card, .difference-card {
  width: 280px;
  padding: 32px;
  justify-content: flex-start;
}

.help-card .card-icon {
  font-size: 32px;
  margin-bottom: 16px;
}

.help-card .card-title {
  font-size: 19px;
  margin-bottom: 8px;
}

.help-card .card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

/* Category Hero */
.category-hero {
  text-align: center;
  padding: 80px 22px 60px;
  background: var(--color-bg-secondary);
}

.category-hero-title {
  font-size: 48px;
  font-weight: 600;
  line-height: 1.08349;
  letter-spacing: -0.003em;
  margin-bottom: 12px;
}

.category-hero-subtitle {
  font-size: 21px;
  color: var(--color-text-secondary);
  margin-bottom: 24px;
}

/* Sticky Section Nav */
.section-nav {
  position: sticky;
  top: 48px;
  z-index: 900;
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
  padding: 12px 22px;
}

.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scrollbar-width: none;
}

.section-nav-inner::-webkit-scrollbar {
  display: none;
}

.section-nav a {
  font-size: 14px;
  font-weight: 400;
  color: var(--color-text);
  opacity: 0.7;
  white-space: nowrap;
  padding: 4px 0;
}

.section-nav a:hover {
  opacity: 1;
  text-decoration: none;
}

/* Guide Cards */
.guide-card {
  width: 280px;
  padding: 32px;
  background: #fff;
  border: 1px solid var(--color-border);
}

.guide-card .card-title {
  font-size: 19px;
  margin-bottom: 8px;
}

.guide-card .card-desc {
  font-size: 14px;
  color: var(--color-text-secondary);
  margin-bottom: 16px;
}

.guide-card .card-cta {
  font-size: 14px;
  color: var(--color-accent);
}

/* Savings Card */
.savings-card {
  width: 280px;
  padding: 32px;
  background: #fff;
  border: 1px solid var(--color-border);
}

/* Quick Links */
.quick-links {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  padding: 40px 22px;
}

.quick-link {
  font-size: 14px;
  color: var(--color-accent);
  padding: 8px 16px;
  border: 1px solid var(--color-border);
  border-radius: 980px;
  transition: var(--transition);
}

.quick-link:hover {
  background: var(--color-bg-secondary);
  text-decoration: none;
}

/* Brand Collab */
.brand-collab {
  padding: var(--section-padding);
  text-align: center;
  background: linear-gradient(135deg, #f5f5f7 0%, #e8e8ed 100%);
}

.brand-collab-title {
  font-size: 40px;
  font-weight: 600;
  margin-bottom: 12px;
}

.brand-collab-desc {
  font-size: 21px;
  color: var(--color-text-secondary);
  max-width: 600px;
  margin: 0 auto 32px;
}

/* Footer */
.footer {
  background: var(--color-bg-secondary);
  padding: 40px 22px 20px;
  font-size: 12px;
  color: var(--color-text-secondary);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 24px;
  margin-bottom: 32px;
}

.footer-column h4 {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 12px;
}

.footer-column ul {
  list-style: none;
}

.footer-column li {
  margin-bottom: 8px;
}

.footer-column a {
  color: var(--color-text-secondary);
  font-size: 12px;
}

.footer-column a:hover {
  color: var(--color-text);
  text-decoration: underline;
}

.footer-bottom {
  border-top: 1px solid var(--color-border);
  padding-top: 16px;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}

.footer-legal {
  max-width: var(--max-width);
  margin: 16px auto 0;
  font-size: 11px;
  line-height: 1.4;
  color: var(--color-text-secondary);
}

/* Footer Accordion (Mobile) */
.footer-column h4 {
  cursor: default;
}

/* Responsive */
@media (max-width: 768px) {
  .product-grid {
    grid-template-columns: 1fr;
    padding: 0 12px 40px;
  }

  .product-tile {
    min-height: 420px;
  }

  .tile-headline {
    font-size: 32px;
  }

  .hero-title {
    font-size: 40px;
  }

  .section-title {
    font-size: 32px;
  }

  .carousel-card {
    width: 280px;
  }

  .carousel-card.wide {
    width: 300px;
  }

  .footer-columns {
    grid-template-columns: 1fr;
  }

  .footer-column h4 {
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 0;
    border-bottom: 1px solid var(--color-border);
    margin-bottom: 0;
  }

  .footer-column h4::after {
    content: "+";
    font-size: 16px;
    font-weight: 400;
    transition: transform 0.3s;
  }

  .footer-column.open h4::after {
    content: "−";
  }

  .footer-column ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-column.open ul {
    max-height: 400px;
    padding-top: 8px;
  }

  .tab-nav {
    gap: 16px;
    overflow-x: auto;
    padding: 0 16px;
    justify-content: flex-start;
  }

  .icon-bar {
    gap: 20px;
  }

  .section-nav-inner {
    gap: 16px;
  }
}

@media (min-width: 769px) {
  .footer-column ul {
    display: block !important;
    max-height: none !important;
  }
}

/* ============================================
   Orchard — Main JavaScript
   ============================================ */

document.addEventListener('DOMContentLoaded', () => {
  initCarousels();
  initTabs();
  initFooterAccordion();
});

/* ---------- Carousels ---------- */
function initCarousels() {
  document.querySelectorAll('.carousel-section').forEach(section => {
    const track = section.querySelector('.carousel-track');
    const prevBtn = section.querySelector('.carousel-btn.prev');
    const nextBtn = section.querySelector('.carousel-btn.next');
    if (!track || !prevBtn || !nextBtn) return;

    const cardWidth = track.querySelector('.carousel-card')?.offsetWidth || 320;
    const gap = 16;
    const scrollAmount = cardWidth + gap;

    function updateButtons() {
      prevBtn.disabled = track.scrollLeft <= 1;
      nextBtn.disabled = track.scrollLeft + track.clientWidth >= track.scrollWidth - 1;
    }

    prevBtn.addEventListener('click', () => {
      track.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
    });

    nextBtn.addEventListener('click', () => {
      track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    });

    track.addEventListener('scroll', updateButtons, { passive: true });
    updateButtons();
  });
}

/* ---------- Entertainment Tabs ---------- */
function initTabs() {
  const tabNavs = document.querySelectorAll('.tab-nav');
  tabNavs.forEach(nav => {
    const buttons = nav.querySelectorAll('.tab-btn');
    const panels = nav.parentElement.querySelectorAll('.tab-panel');

    buttons.forEach(btn => {
      btn.addEventListener('click', () => {
        const target = btn.dataset.tab;
        buttons.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        panels.forEach(p => {
          p.classList.toggle('active', p.dataset.panel === target);
        });
      });
    });
  });
}

/* ---------- Footer Accordion ---------- */
function initFooterAccordion() {
  const isMobile = () => window.innerWidth <= 768;

  document.querySelectorAll('.footer-column').forEach(col => {
    const heading = col.querySelector('h4');
    if (!heading) return;

    heading.addEventListener('click', () => {
      if (!isMobile()) return;
      col.classList.toggle('open');
    });
  });
}

